 async function downloadComplaint(row:any){
  const d=row.final_details||row.details||{};
  const esc=(v:any)=>String(v??'—').replace(/[&<>"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[m]||m));
  const witnesses=(d.witnesses||[]).map((w:any,i:number)=>'<li>Témoin '+(i+1)+' : '+esc([w.last_name,w.first_name].filter(Boolean).join(' '))+' · '+esc(w.phone)+'</li>').join('');
  const html='<!doctype html><html lang="fr"><head><meta charset="utf-8"><title>Dépôt de plainte LSPD</title><style>body{font:15px Arial;background:#071017;color:#dce8f0;padding:30px}main{max-width:980px;margin:auto}header,section{border:1px solid #294052;background:#0c141b;padding:20px;margin:18px 0}h1,h2{color:#fff}h2{font-size:16px;color:#7fc7ff}dt{font-weight:700;color:#9eb4c7;margin-top:10px}dd{margin:3px 0 10px;white-space:pre-wrap}</style></head><body><main><header><h1>LOS SANTOS POLICE DEPARTMENT</h1><p>VESPUCCI DIVISION · DÉPÔT DE PLAINTE DÉFINITIF</p></header><section><h2>AGENT RÉDACTEUR</h2><dl><dt>Agent</dt><dd>'+esc(row.opened_by?.display_name)+'</dd><dt>Matricule</dt><dd>'+esc(row.opened_by?.badge_number)+'</dd><dt>Date / heure</dt><dd>'+esc([d.report_date,d.report_time].filter(Boolean).join(' · '))+'</dd></dl></section><section><h2>PLAIGNANT</h2><dl><dt>Identité</dt><dd>'+esc([d.last_name,d.first_name].filter(Boolean).join(' '))+'</dd><dt>Date de naissance</dt><dd>'+esc(d.birth_date)+'</dd><dt>SSN</dt><dd>'+esc(d.ssn)+'</dd><dt>Profession</dt><dd>'+esc(d.profession)+'</dd><dt>Adresse domicile</dt><dd>'+esc(d.home_address)+'</dd><dt>Téléphone</dt><dd>'+esc(d.phone)+'</dd></dl></section><section><h2>ÉVÉNEMENT</h2><dl><dt>Date / heure</dt><dd>'+esc([d.event_date,d.event_time].filter(Boolean).join(' · '))+'</dd><dt>Lieu / adresse</dt><dd>'+esc([d.event_place,d.event_address].filter(Boolean).join(' · '))+'</dd><dt>Objet</dt><dd>'+esc(d.complaint_type)+'</dd><dt>Déclaration</dt><dd>'+esc(d.statement)+'</dd></dl></section><section><h2>SUSPECT(S)</h2><dl><dt>Nom / prénom</dt><dd>'+esc(d.suspect_name)+'</dd><dt>Description</dt><dd>'+esc(d.suspect_description)+'</dd><dt>Adresse</dt><dd>'+esc(d.suspect_address)+'</dd><dt>Lien avec le plaignant</dt><dd>'+esc(d.suspect_link)+'</dd></dl></section><section><h2>TÉMOINS</h2><ul>'+witnesses+'</ul></section><section><h2>PRÉJUDICES & PIÈCES</h2><dl><dt>Préjudice matériel</dt><dd>'+esc(d.material_damage?d.material_damage+' $':'—')+'</dd><dt>Préjudice corporel</dt><dd>'+esc(d.bodily_harm)+'</dd><dt>Autre préjudice</dt><dd>'+esc(d.other_damage)+'</dd><dt>Pièces / références</dt><dd>'+esc(d.evidence_details)+'</dd></dl></section><section><h2>DÉCLARATION SUR L’HONNEUR</h2><p>Je soussigné(e) '+esc(d.sworn_name)+' certifie que les informations fournies dans ce dépôt de plainte sont exactes et sincères. Je suis informé(e) que toute fausse déclaration est passible de poursuites pénales.</p><dl><dt>Signature plaignant</dt><dd>'+esc(d.complainant_signature)+'</dd><dt>Signature agent</dt><dd>'+esc(d.officer_signature)+'</dd></dl></section></main></body></html>';
  const files:Record<string,Uint8Array>={'rapport.html':strToU8(html)};
  const urls=[...new Set([d.id_photo,...String(d.evidence_photo_links||'').split(/[\n,;\s]+/),...String(d.evidence_details||'').split(/[\n,;\s]+/)].filter((x:any)=>/^https?:\/\//i.test(String(x))))] as string[];
  const unavailable:string[]=[];
  const blobToPng=async(blob:Blob)=>{const bitmap=await createImageBitmap(blob);const canvas=document.createElement('canvas');canvas.width=bitmap.width;canvas.height=bitmap.height;const ctx=canvas.getContext('2d');if(!ctx)throw new Error('Canvas indisponible');ctx.drawImage(bitmap,0,0);bitmap.close();const png=await new Promise<Blob>((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error('Conversion PNG impossible')),'image/png'));return new Uint8Array(await png.arrayBuffer())};
  let photoNumber=1;
  for(const url of urls){try{const res=await fetch(url);if(!res.ok)throw new Error(String(res.status));const blob=await res.blob();files['photos/photo-'+String(photoNumber).padStart(2,'0')+'.png']=await blobToPng(blob)}catch{unavailable.push(url)}photoNumber++}
  files['photos/README.txt']=strToU8(urls.length?'Photos jointes au dépôt de plainte. Les images récupérables sont converties en PNG et réunies dans ce dossier.':'Aucune photo jointe au dépôt de plainte.');
  if(unavailable.length)files['photos/photos-indisponibles.txt']=strToU8('Ces photos n’ont pas pu être récupérées automatiquement. Liens originaux :\\n\\n'+unavailable.join('\\n'));
  const blob=new Blob([zipSync(files,{level:6})],{type:'application/zip'}),a=document.createElement('a');
  const safe=String(d.last_name||'PLAIGNANT').replace(/[^a-zA-Z0-9_-]+/g,'-');
  a.download='LSPD-DEPOT-DE-PLAINTE-'+safe+'-'+String(d.report_date||d.event_date||'archive')+'.zip';
  a.href=URL.createObjectURL(blob);document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)
 }
 async function uploadK9Media(dog:string,kind:'photo'|'checkup',file:File|null){if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)){setError('Format non pris en charge. Utilisez une image PNG, JPG ou WEBP.');return}if(file.size>10*1024*1024){setError('Image trop volumineuse (10 Mo maximum).');return}setError('');const key=dog+'/'+kind;setK9UploadBusy(dog+'-'+kind);const {error:e}=await supabase.storage.from('k9-media').upload(key,file,{upsert:true,contentType:file.type,cacheControl:'0'});setK9UploadBusy(null);if(e)setError(e.message);else setK9MediaVersion(v=>v+1)}
 function k9MediaUrl(dog:string,kind:'photo'|'checkup'){return supabase.storage.from('k9-media').getPublicUrl(dog+'/'+kind).data.publicUrl+'?v='+k9MediaVersion}
 async function loadK9Units(){const {data,error:e}=await supabase.from('k9_units').select('*').order('created_at');if(e)setError(e.message);else setK9Units(data||[])}
 async function createK9Unit(){if(!newK9.handler_name.trim()||!newK9.badge_number.trim()||!newK9.dog_name.trim()||!newK9.dog_age||!newK9.dog_sex.trim()||!newK9.dog_breed.trim()||!newK9.training_date)return setError('Tous les champs de l’unité cynophile sont obligatoires.');setBusy(true);setError('');const {data,error:e}=await supabase.from('k9_units').insert({...newK9,handler_name:newK9.handler_name.trim(),badge_number:newK9.badge_number.trim(),dog_name:newK9.dog_name.trim(),dog_age:Number(newK9.dog_age),dog_sex:newK9.dog_sex.trim(),dog_breed:newK9.dog_breed.trim(),created_by:staff.id}).select('*').single();setBusy(false);if(e){setError(e.message);return}setK9Units(prev=>[...prev,data]);setNewK9({handler_name:'',badge_number:'',dog_name:'',dog_age:'',dog_sex:'',dog_breed:'',training_date:''})}
 async function deleteK9Unit(unit:any){if(!k9CanCreate)return;if(!confirm('Supprimer définitivement l’unité cynophile de '+unit.handler_name+' et '+unit.dog_name+' ?'))return;setBusy(true);setError('');const paths=[unit.media_key+'/photo',unit.media_key+'/checkup'];const {error:se}=await supabase.storage.from('k9-media').remove(paths);if(se){setBusy(false);setError(se.message);return}const {error:e}=await supabase.from('k9_units').delete().eq('id',unit.id);setBusy(false);if(e){setError(e.message);return}setK9Units(prev=>prev.filter(x=>x.id!==unit.id));if(selectedK9?.id===unit.id)setSelectedK9(null)}


 async function loadDoaProfiles(){const {data,error:e}=await supabase.from('doa_profiles').select('*').order('created_at');if(e)setError(e.message);else setDoaProfiles(data||[])}
 async function createDoaProfile(){if(!newDoaName.trim()||!newDoaBadge.trim())return setError("L'identité et le matricule sont obligatoires.");setBusy(true);setError('');const {data,error:e}=await supabase.from('doa_profiles').insert({agent_name:newDoaName.trim(),badge_number:newDoaBadge.trim(),created_by:staff.id}).select('*').single();setBusy(false);if(e){setError(e.message);return}setDoaProfiles(prev=>[...prev,data]);setNewDoaName('');setNewDoaBadge('')}
 async function deleteDoaProfile(profile:any){if(!doaCanCreate)return;if(!confirm('Supprimer définitivement le carnet DOA de '+profile.agent_name+' (matricule '+profile.badge_number+'), ainsi que toutes ses tuiles, posts et photos ?'))return;setBusy(true);setError('');const {data:tiles,error:te}=await supabase.from('doa_tiles').select('id').eq('owner_badge',profile.badge_number);if(te){setBusy(false);setError(te.message);return}const ids=(tiles||[]).map((t:any)=>t.id);if(ids.length){const {data:imgs,error:ie}=await supabase.from('doa_tile_images').select('image_path').in('tile_id',ids);if(ie){setBusy(false);setError(ie.message);return}if(imgs?.length){const {error:se}=await supabase.storage.from('doa-media').remove(imgs.map((x:any)=>x.image_path));if(se){setBusy(false);setError(se.message);return}}const {error:de}=await supabase.from('doa_tiles').delete().in('id',ids);if(de){setBusy(false);setError(de.message);return}}const {error:e}=await supabase.from('doa_profiles').delete().eq('id',profile.id);setBusy(false);if(e){setError(e.message);return}setDoaProfiles(prev=>prev.filter(x=>x.id!==profile.id));if(doaProfile?.badge===profile.badge_number){setDoaProfile(null);setSelectedDoaTile(null);setDoaTiles([]);setDoaPosts([]);setDoaTileImages([])}}
 async function loadDoaProfile(badge:string,name:string){setDoaProfile({badge,name});setSelectedDoaTile(null);setDoaPosts([]);setDoaTileImages([]);const {data,error:e}=await supabase.from('doa_tiles').select('*').eq('owner_badge',badge).order('created_at',{ascending:false});if(e)setError(e.message);else setDoaTiles(data||[])}
 async function createDoaTile(){if(!doaTileTitle.trim()){setError('Le nom de la tuile est obligatoire.');return}setBusy(true);setError('');const {data,error:e}=await supabase.from('doa_tiles').insert({owner_badge:doaProfile?.badge||'53',title:doaTileTitle.trim(),created_by:staff.id}).select('*').single();setBusy(false);if(e){setError(e.message);return}setDoaTiles(prev=>[data,...prev]);setDoaTileTitle('')}
 async function deleteDoaTile(tile:any){if(!confirm('Supprimer définitivement la tuile « '+tile.title+' », tous ses posts et toutes ses photos ?'))return;setBusy(true);setError('');const {data:imgs,error:ie}=await supabase.from('doa_tile_images').select('image_path').eq('tile_id',tile.id);if(ie){setBusy(false);setError(ie.message);return}if(imgs?.length){const {error:se}=await supabase.storage.from('doa-media').remove(imgs.map((x:any)=>x.image_path));if(se){setBusy(false);setError(se.message);return}}const {error:e}=await supabase.from('doa_tiles').delete().eq('id',tile.id);setBusy(false);if(e){setError(e.message);return}setDoaTiles(prev=>prev.filter(t=>t.id!==tile.id));if(selectedDoaTile?.id===tile.id){setSelectedDoaTile(null);setDoaPosts([]);setDoaTileImages([])}}
 async function openDoaTile(tile:any){setSelectedDoaTile(tile);setDoaTileImagesFiles([]);setDoaPostNotes('');const [{data:posts,error:pe},{data:images,error:ie}]=await Promise.all([supabase.from('doa_posts').select('*').eq('tile_id',tile.id).order('created_at',{ascending:false}),supabase.from('doa_tile_images').select('*').eq('tile_id',tile.id).order('created_at',{ascending:false})]);if(pe||ie)setError(pe?.message||ie?.message||'Erreur');else{setDoaPosts(posts||[]);setDoaTileImages(images||[])}}
 async function addDoaPost(){if(!selectedDoaTile||!doaTileImagesFiles.length)return setError('Sélectionnez au moins une photo.');const files=[...doaTileImagesFiles];if(files.some(file=>file.size>10*1024*1024))return setError('Une image est trop volumineuse (10 Mo maximum par image).');setBusy(true);setError('');const {data:post,error:pe}=await supabase.from('doa_posts').insert({tile_id:selectedDoaTile.id,details:doaPostNotes.trim(),created_by:staff.id}).select('*').single();if(pe){setBusy(false);setError(pe.message);return}const uploaded:{id:string,path:string}[]=[];for(const file of files){const id=crypto.randomUUID(),path=(doaProfile?.badge||selectedDoaTile.owner_badge||'53')+'/'+selectedDoaTile.id+'/'+post.id+'/'+id;const {error}=await supabase.storage.from('doa-media').upload(path,file,{contentType:file.type||'image/jpeg',cacheControl:'0'});if(error){await supabase.storage.from('doa-media').remove(uploaded.map(x=>x.path));await supabase.from('doa_posts').delete().eq('id',post.id);setBusy(false);setError(error.message);return}uploaded.push({id,path})}const rows=uploaded.map(x=>({id:x.id,tile_id:selectedDoaTile.id,post_id:post.id,image_path:x.path,details:'',created_by:staff.id}));const {data:added,error:ie}=await supabase.from('doa_tile_images').insert(rows).select('*');if(ie){await supabase.storage.from('doa-media').remove(uploaded.map(x=>x.path));await supabase.from('doa_posts').delete().eq('id',post.id);setBusy(false);setError(ie.message);return}setDoaPosts(prev=>[post,...prev]);setDoaTileImages(prev=>[...(added||[]),...prev]);setDoaTileImagesFiles([]);setDoaPostNotes('');setBusy(false)}
 async function saveDoaPostEdit(post:any){setBusy(true);setError('');const {data:updated,error:pe}=await supabase.from('doa_posts').update({details:editDoaNotes.trim()}).eq('id',post.id).select('*').single();if(pe){setBusy(false);setError(pe.message);return}const added:any[]=[];for(const file of editDoaFiles){if(file.size>10*1024*1024){setBusy(false);setError('Une image est trop volumineuse (10 Mo maximum par image).');return}const imageId=crypto.randomUUID(),path=(doaProfile?.badge||selectedDoaTile.owner_badge||'53')+'/'+selectedDoaTile.id+'/'+post.id+'/'+imageId;const {error:ue}=await supabase.storage.from('doa-media').upload(path,file,{contentType:file.type,cacheControl:'0'});if(ue){setBusy(false);setError(ue.message);return}const {data,error:ie}=await supabase.from('doa_tile_images').insert({id:imageId,tile_id:selectedDoaTile.id,post_id:post.id,image_path:path,details:'',created_by:staff.id}).select('*').single();if(ie){setBusy(false);setError(ie.message);return}added.push(data)}setDoaPosts(prev=>prev.map(p=>p.id===post.id?updated:p));if(added.length)setDoaTileImages(prev=>[...added,...prev]);setEditingDoaPost(null);setEditDoaFiles([]);setBusy(false)}
