 async function closeOperation(id:string){if(!operationType)return;setBusy(true);setError('');const now=new Date().toISOString();const draft=selectedOperation?.id===id?(operationType==='robbery'?robberyDetails:operationType==='shooting'?shootingDetails:operationType==='swat'?swatDetails:operationType==='search'?searchDetails:(selectedOperation.details||{})):(operations.find((o:any)=>o.id===id)?.details||{});const archiveDate=draft.date?new Date(String(draft.date)+'T12:00:00').toLocaleDateString('fr-FR'):new Date(now).toLocaleDateString('fr-FR');const archiveTitle=operationType==='robbery'?['BRAQUAGE',String(draft.robbery_type||'TYPE NON RENSEIGNÉ').toUpperCase(),archiveDate].join(' · '):operationType==='shooting'?['FUSILLADE',String(draft.location||'LIEU NON RENSEIGNÉ').toUpperCase(),archiveDate].join(' · '):operationType==='swat'?['OPÉRATION SWAT',String(draft.operation_kind||'TYPE NON RENSEIGNÉ').toUpperCase(),archiveDate].join(' · '):operationType==='search'?['PERQUISITION',String(draft.search_type||'TYPE NON RENSEIGNÉ').toUpperCase(),archiveDate].join(' · '):operationMeta[operationType][0];const {error:e}=await supabase.from('police_operations').update({status:'closed',title:archiveTitle,details:draft,final_details:draft,finalized_at:now,closed_at:now,updated_at:now}).eq('id',id).eq('status','active');setBusy(false);if(e)setError(e.message);else{setSelectedOperation(null);setOperationView('home');const {data}=await supabase.from('police_operations').select('*').eq('operation_type',operationType).eq('status','active').order('created_at',{ascending:false});setOperations(data||[])}}
