function ShootingForm({value,onChange,saveState,readOnly=false}:{value:any;onChange:(v:any)=>void;saveState:'idle'|'saving'|'saved'|'error';readOnly?:boolean}){
 const set=(k:string,v:any)=>onChange({...value,[k]:v});
 const yn=(k:string,label:string)=> <div className="robbery-check"><span>{label}</span><div className="robbery-binary"><label><input type="checkbox" checked={value[k]==='oui'} onChange={()=>set(k,value[k]==='oui'?'':'oui')}/><b>OUI</b></label><label><input type="checkbox" checked={value[k]==='non'} onChange={()=>set(k,value[k]==='non'?'':'non')}/><b>NON</b></label></div></div>;
 const count=Math.max(0,Number(value.gunshot_injured_count)||0);
 const injured=Array.isArray(value.gunshot_injured)?value.gunshot_injured:[];
 const arrestedCount=Math.max(0,Number(value.arrested_count)||0);
 const arrested=Array.isArray(value.arrested_individuals)?value.arrested_individuals:[];
 const setCount=(raw:string)=>{const n=Math.max(0,Number(raw)||0);set('gunshot_injured_count',raw);onChange({...value,gunshot_injured_count:raw,gunshot_injured:Array.from({length:n},(_,i)=>injured[i]||{})})};
 const setInjured=(i:number,k:string,v:any)=>{const next=Array.from({length:count},(_,x)=>({...injured[x]}));next[i]={...next[i],[k]:v};onChange({...value,gunshot_injured:next})};
 const setArrestedCount=(raw:string)=>{const n=Math.max(0,Number(raw)||0);onChange({...value,arrested_count:raw,arrested_individuals:Array.from({length:n},(_,i)=>arrested[i]||{})})};
 const setArrested=(i:number,k:string,v:any)=>{const next=Array.from({length:arrestedCount},(_,x)=>({...arrested[x]}));next[i]={...next[i],[k]:v};onChange({...value,arrested_individuals:next})};
 const arrestedYn=(i:number,k:string,label:string)=> <div className="robbery-check"><span>{label}</span><div className="robbery-binary"><label><input type="checkbox" checked={arrested[i]?.[k]==='oui'} onChange={()=>setArrested(i,k,arrested[i]?.[k]==='oui'?'':'oui')}/><b>OUI</b></label><label><input type="checkbox" checked={arrested[i]?.[k]==='non'} onChange={()=>setArrested(i,k,arrested[i]?.[k]==='non'?'':'non')}/><b>NON</b></label></div></div>;
 const personYn=(i:number,k:string,label:string)=> <div className="robbery-check"><span>{label}</span><div className="robbery-binary"><label><input type="checkbox" checked={injured[i]?.[k]==='oui'} onChange={()=>setInjured(i,k,injured[i]?.[k]==='oui'?'':'oui')}/><b>OUI</b></label><label><input type="checkbox" checked={injured[i]?.[k]==='non'} onChange={()=>setInjured(i,k,injured[i]?.[k]==='non'?'':'non')}/><b>NON</b></label></div></div>;
 return <fieldset className="robbery-form" disabled={readOnly}>
  <div className="robbery-form-head"><div><small>FICHE OPÉRATIONNELLE</small><h3>FUSILLADE</h3></div><span className={`autosave-state ${saveState}`}>{saveState==='saving'?'BROUILLON…':saveState==='saved'?'BROUILLON ENREGISTRÉ':saveState==='error'?'ERREUR DE SAUVEGARDE':'BROUILLON AUTOMATIQUE'}</span></div>
  <section className="robbery-block"><h4>INTERVENTION</h4><div className="robbery-grid"><label>Date<input type="date" value={value.date??''} onChange={e=>set('date',e.target.value)}/></label><label>Heure<input type="time" value={value.time??''} onChange={e=>set('time',e.target.value)}/></label><label>Lieu<input value={value.location??''} onChange={e=>set('location',e.target.value)} placeholder="Lieu de la fusillade"/></label><label>Nombre de blessés par balle<input type="number" min="0" value={value.gunshot_injured_count??''} onChange={e=>setCount(e.target.value)}/></label><label>Nombre d’individus arrêtés<input type="number" min="0" value={value.arrested_count??''} onChange={e=>setArrestedCount(e.target.value)}/></label></div></section>
  <section className="robbery-block"><h4>BLESSÉS PAR BALLE / ARRÊTÉS</h4><p>Les fiches individuelles sont générées automatiquement selon les nombres renseignés.</p></section>
  <section className="robbery-block"><h4>FORCES DE L’ORDRE</h4><div className="robbery-yesno">{yn('law_force_used','Usage de la force par les forces de l’ordre')}</div></section>
  {Array.from({length:count},(_,i)=><section className="robbery-block" key={i}><h4>BLESSÉ PAR BALLE #{i+1}</h4><div className="robbery-grid"><label>Identité / informations<input value={injured[i]?.identity??''} onChange={e=>setInjured(i,'identity',e.target.value)} placeholder="Nom, prénom, numéro d’identité…"/></label><label className="photo-zone">PHOTO CARTE D’IDENTITÉ<input value={injured[i]?.id_photo??''} onChange={e=>setInjured(i,'id_photo',e.target.value)} placeholder="Lien WebP de la carte d’identité"/></label><label className="photo-zone">PHOTO AU MOMENT DES FAITS<input value={injured[i]?.scene_photo??''} onChange={e=>setInjured(i,'scene_photo',e.target.value)} placeholder="Lien WebP de la personne"/></label></div><div className="robbery-yesno">{personYn(i,'ppa','PPA')}</div><h4>DROITS MIRANDA</h4><div className="robbery-grid"><label>Droits Miranda lus le<input type="date" value={injured[i]?.miranda_date??''} onChange={e=>setInjured(i,'miranda_date',e.target.value)}/></label><label>À<input type="time" value={injured[i]?.miranda_time??''} onChange={e=>setInjured(i,'miranda_time',e.target.value)}/></label><label>Lieu de lecture<select value={injured[i]?.miranda_location??''} onChange={e=>setInjured(i,'miranda_location',e.target.value)}><option value="">Sélectionner…</option><option value="voiture">Devant la voiture</option><option value="poste">Au poste</option></select></label></div><h4>OBJETS ILLÉGAUX RETROUVÉS</h4><div className="robbery-grid"><label>Arme<textarea value={injured[i]?.weapon??''} onChange={e=>setInjured(i,'weapon',e.target.value)} placeholder="Arme(s) retrouvée(s)"/></label><label>Munitions<textarea value={injured[i]?.ammo??''} onChange={e=>setInjured(i,'ammo',e.target.value)} placeholder="Munitions retrouvées"/></label><label>Drogue<textarea value={injured[i]?.drugs??''} onChange={e=>setInjured(i,'drugs',e.target.value)} placeholder="Drogue(s) retrouvée(s)"/></label></div></section>)}
 {Array.from({length:arrestedCount},(_,i)=><section className="robbery-block" key={'arrested-'+i}><h4>INDIVIDU ARRÊTÉ #{i+1}</h4><div className="robbery-grid"><label>Identité / informations<input value={arrested[i]?.identity??''} onChange={e=>setArrested(i,'identity',e.target.value)} placeholder="Nom, prénom, numéro d’identité…"/></label><label className="photo-zone">PHOTO CARTE D’IDENTITÉ<input value={arrested[i]?.id_photo??''} onChange={e=>setArrested(i,'id_photo',e.target.value)} placeholder="Lien WebP de la carte d’identité"/></label><label className="photo-zone">PHOTO AU MOMENT DES FAITS<input value={arrested[i]?.scene_photo??''} onChange={e=>setArrested(i,'scene_photo',e.target.value)} placeholder="Lien WebP de la personne"/></label></div><div className="robbery-yesno">{arrestedYn(i,'ppa','PPA')}</div><h4>DROITS MIRANDA</h4><div className="robbery-grid"><label>Droits Miranda lus le<input type="date" value={arrested[i]?.miranda_date??''} onChange={e=>setArrested(i,'miranda_date',e.target.value)}/></label><label>À<input type="time" value={arrested[i]?.miranda_time??''} onChange={e=>setArrested(i,'miranda_time',e.target.value)}/></label><label>Lieu de lecture<select value={arrested[i]?.miranda_location??''} onChange={e=>setArrested(i,'miranda_location',e.target.value)}><option value="">Sélectionner…</option><option value="voiture">Devant la voiture</option><option value="poste">Au poste</option></select></label></div><h4>OBJETS ILLÉGAUX RETROUVÉS</h4><div className="robbery-grid"><label>Arme<textarea value={arrested[i]?.weapon??''} onChange={e=>setArrested(i,'weapon',e.target.value)} placeholder="Arme(s) retrouvée(s)"/></label><label>Munitions<textarea value={arrested[i]?.ammo??''} onChange={e=>setArrested(i,'ammo',e.target.value)} placeholder="Munitions retrouvées"/></label><label>Drogue<textarea value={arrested[i]?.drugs??''} onChange={e=>setArrested(i,'drugs',e.target.value)} placeholder="Drogue(s) retrouvée(s)"/></label></div></section>)}
  </fieldset>
}

